import{_ as l,a0 as r,w as a,s as u,ao as p,I as o,x as n,a1 as e,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"使用 Syncthing 在多個設備間同步文件 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Syncthing 在多個設備間同步文件 | LCTT (202001) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Syncthing 在多個設備間同步文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Syncthing 在多個設備間同步文件 | LCTT (202001) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202001/20200111 Sync files across multiple devices with Syncthing","title":"使用 Syncthing 在多個設備間同步文件","tag":"202001","desc":""},"relativePath":"202001/20200111 Sync files across multiple devices with Syncthing.md","filePath":"[post].md"}'),d={name:"202001/20200111 Sync files across multiple devices with Syncthing.md"};function g(y,t,m,S,h,c){const i=r("Link");return a(),u("div",null,[t[18]||(t[18]=p('<h1 id="使用-syncthing-在多個設備間同步文件" tabindex="-1">使用 Syncthing 在多個設備間同步文件 <a class="header-anchor" href="#使用-syncthing-在多個設備間同步文件" aria-label="Permalink to “使用 Syncthing 在多個設備間同步文件”">​</a></h1><blockquote><p>2020 年，在我們的 20 個使用開源提升生產力的系列文章中，首先了解如何使用 Syncthing 同步文件。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202001/18/123416rebvs7sjwm6c889y.jpg" alt=""></p><p>去年，我在 19 天裏給你介紹了 19 個新（對你而言）的生產力工具。今年，我換了一種方式：使用你在使用或者還沒使用的工具，構建一個使你可以在新一年更加高效的環境。</p><h3 id="使用-synthing-同步文件" tabindex="-1">使用 Synthing 同步文件 <a class="header-anchor" href="#使用-synthing-同步文件" aria-label="Permalink to “使用 Synthing 同步文件”">​</a></h3><p>設置新機器很麻煩。我們都有在機器之間複製的“標準設置”。多年來，我使用了很多方法來使它們在計算機之間同步。在過去（這會告訴你我年紀有多大了），曾經是軟盤、然後是 Zip 磁盤、U 盤、SCP、Rsync、Dropbox、ownCloud，你想到的都試過。但這些似乎對我都不夠好。</p>',6)),o("p",null,[t[1]||(t[1]=n("然後我偶然發現了 ",-1)),e(i,{href:"https://syncthing.net/"},{default:s(()=>[...t[0]||(t[0]=[n("Syncthing",-1)])]),_:1}),t[2]||(t[2]=n("。",-1))]),t[19]||(t[19]=p('<p><img src="https://opensource.com/sites/default/files/uploads/productivity_1-1.png" alt="syncthing console" title="syncthing console"></p><p>Syncthing 是一個輕量級的點對點文件同步系統。你不需要為服務付費，也不需要第三方服務器，而且速度很快。以我的經驗，比文件同步中的許多“大牌”要快得多。</p><p>Syncthing 可在 Linux、MacOS、Windows 和多種 BSD 中使用。還有一個 Android 應用（但尚無官方 iOS 版本）。以上所有終端都有方便的圖形化前端（儘管我不會在這裏介紹）。在 Linux 上，大多數發行版都有可用的軟件包，因此安裝非常簡單。</p><p><img src="https://opensource.com/sites/default/files/uploads/productivity_1-2.png" alt="Installing Syncthing on Ubuntu" title="Installing Syncthing on Ubuntu"></p><p>首次啓動 Syncthing 時，它將啓動 Web 瀏覽器以配置守護程序。第一台計算機上沒有太多要做，但是這是一個很好的機會來介紹一下用户界面 （UI）。最重要的是在右上方的 “Actions” 菜單下的 “System ID”。</p><p><img src="https://opensource.com/sites/default/files/uploads/productivity_1-3.png" alt="Machine ID" title="Machine ID"></p><p>設置第一台計算機後，請在第二台計算機上重複安裝。在 UI 中，右下方將顯示一個按鈕，名為 “Add Remote Device”。單擊該按鈕，你將會看到一個要求輸入 “Device ID and a Name” 的框。從第一台計算機上覆制並粘貼 “Device ID”，然後單擊 “Save”。</p><p>你應該會在第一台上看到一個請求添加第二台的彈出窗口。接受後，新機器將顯示在第一台機器的右下角。與第二台計算機共享默認目錄。單擊 “Default Folder”，然後單擊 “Edit” 按鈕。彈出窗口的頂部有四個鏈接。單擊 “Sharing”，然後選擇第二台計算機。單擊 “Save”，然後查看第二台計算機。你會看到一個接受共享目錄的提示。接受後，它將開始在兩台計算機之間同步文件。</p><p><img src="https://opensource.com/sites/default/files/uploads/productivity_1-4.png" alt="Sharing a directory in Syncthing" title="Sharing a directory in Syncthing"></p><p>測試從一台計算機上覆制文件到默認目錄（“/你的家目錄/Share”）。它應該很快會在另一台上出現。</p><p>你可以根據需要添加任意數量的目錄，這非常方便。如你在第一張圖中所看到的，我有一個用於保存配置的 <code>myconfigs</code> 文件夾。當我買了一台新機器時，我只需安裝 Syncthing，如果我在一台機器上調整了配置，我不必更新所有，它會自動更新。</p><hr>',12)),o("p",null,[t[4]||(t[4]=n("via: ",-1)),e(i,{href:"https://opensource.com/article/20/1/sync-files-syncthing"},{default:s(()=>[...t[3]||(t[3]=[n("https://opensource.com/article/20/1/sync-files-syncthing",-1)])]),_:1})]),o("p",null,[t[9]||(t[9]=n("作者：",-1)),e(i,{href:"https://opensource.com/users/ksonney"},{default:s(()=>[...t[5]||(t[5]=[n("Kevin Sonney",-1)])]),_:1}),t[10]||(t[10]=n(" 選題：",-1)),e(i,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[6]||(t[6]=[n("lujun9972",-1)])]),_:1}),t[11]||(t[11]=n(" 譯者：",-1)),e(i,{href:"https://github.com/geekpi"},{default:s(()=>[...t[7]||(t[7]=[n("geekpi",-1)])]),_:1}),t[12]||(t[12]=n(" 校對：",-1)),e(i,{href:"https://github.com/wxy"},{default:s(()=>[...t[8]||(t[8]=[n("wxy",-1)])]),_:1})]),o("p",null,[t[15]||(t[15]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[13]||(t[13]=[n("LCTT",-1)])]),_:1}),t[16]||(t[16]=n(" 原創編譯，",-1)),e(i,{href:"https://linux.cn/"},{default:s(()=>[...t[14]||(t[14]=[n("Linux中國",-1)])]),_:1}),t[17]||(t[17]=n(" 榮譽推出",-1))])])}const v=l(d,[["render",g]]);export{C as __pageData,v as default};
